+      Set<ModuleKey> parents = new HashSet<>(module.getDependants());
+      if (options.includeUnused) {
+        parents.addAll(module.getOriginalDependants());
+      }
+      for (ModuleKey parent : parents) {
+        if (seen.contains(parent)) {
