+    }
+
+    void shutdown(BuildToolLogCollection logs) throws InterruptedException {
+      enqueue(INVOCATION_COMPLETED);
+      long blockedMs = blockedMillis.get();
+      if (blockedMs > 100) {
+        BugReport.sendBugReport(new ActionDumpQueueFullException(blockedMs));
+      }
